    ra_narrow(guest + 4, host + 8, 4, 4, 0, "the host's tagMSG.message does not fit in 4 bytes");
    ra_narrow(guest + 8, host + 16, 4, 8, 0, "the host's tagMSG.wParam does not fit in 4 bytes");
    ra_narrow(guest + 12, host + 24, 4, 8, 1, "the host's tagMSG.lParam does not fit in 4 bytes");
    ra_narrow(guest + 16, host + 32, 4, 4, 0, "the host's tagMSG.time does not fit in 4 bytes");
    ra_narrow(guest + 20, host + 36, 4, 4, 0, "the host's tagMSG.pt.x does not fit in 4 bytes");
    ra_narrow(guest + 24, host + 40, 4, 4, 0, "the host's tagMSG.pt.y does not fit in 4 bytes");
